import{_ as s,o as e,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"52. 预处理器和宏","description":"The Little Book of C 中文版 — 52. 预处理器和宏","frontmatter":{"title":"52. 预处理器和宏","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","06-编译与构建","中文"],"description":"The Little Book of C 中文版 — 52. 预处理器和宏","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":52,"sidebarWeight":52,"alternateZh":"/posts/c教程/zh-CN/06-编译与构建/052-The Preprocessor and Macros","alternateEn":"/posts/c教程/en-US/06-Compilation and Build/052-The Preprocessor and Macros"},"headers":[],"relativePath":"posts/c教程/zh-CN/06-编译与构建/052-The Preprocessor and Macros.md","filePath":"posts/c教程/zh-CN/06-编译与构建/052-The Preprocessor and Macros.md","lastUpdated":1790163617000}'),p={name:"posts/c教程/zh-CN/06-编译与构建/052-The Preprocessor and Macros.md"};function i(o,a,d,l,c,r){return e(),n("div",null,[...a[0]||(a[0]=[t(`<p>[English version](/posts/c教程/en-US/06-Compilation and Build/052-The Preprocessor and Macros)</p><p>在编译 C 代码之前，它会经过一个强大的文本处理阶段，称为预处理器。这是包含头文件、扩展宏和进行条件编译的地方。</p><p>预处理器不“理解”C，它执行文本替换和文件包含，为编译器准备代码。</p><h4 id="步骤-1-预处理器的作用" tabindex="-1">步骤 1. 预处理器的作用 <a class="header-anchor" href="#步骤-1-预处理器的作用" aria-label="Permalink to &quot;步骤 1. 预处理器的作用&quot;">​</a></h4><p>每一行以<code>#</code>是一个预处理器指令。常见的包括：</p><table tabindex="0"><thead><tr><th>指令</th><th>目的</th></tr></thead><tbody><tr><td><code>#include</code></td><td>插入头文件的内容</td></tr><tr><td><code>#define</code></td><td>定义宏或常量</td></tr><tr><td><code>#undef</code></td><td>删除宏定义</td></tr><tr><td><code>#if</code>,<code>#ifdef</code>,<code>#ifndef</code></td><td>条件编译</td></tr><tr><td><code>#else</code>,<code>#elif</code>,<code>#endif</code></td><td>预处理器的分支逻辑</td></tr><tr><td><code>#error</code></td><td>停止编译并显示消息</td></tr><tr><td><code>#pragma</code></td><td>编译器特定指令</td></tr></tbody></table><h4 id="小代码-查看实际效果" tabindex="-1">小代码：查看实际效果 <a class="header-anchor" href="#小代码-查看实际效果" aria-label="Permalink to &quot;小代码：查看实际效果&quot;">​</a></h4><p>创造<code>macro.c</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#define PI 3.14159</span></span>
<span class="line"><span>#define CIRCLE_AREA(r) (PI * (r) * (r))</span></span>
<span class="line"><span>#define SQUARE(x) ((x) * (x))</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;PI = %.2f\\n&quot;, PI);</span></span>
<span class="line"><span>    printf(&quot;Area of circle (r=2): %.2f\\n&quot;, CIRCLE_AREA(2));</span></span>
<span class="line"><span>    printf(&quot;Square of 5: %d\\n&quot;, SQUARE(5));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译并运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc macro.c -o macro</span></span>
<span class="line"><span>./macro</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PI = 3.14</span></span>
<span class="line"><span>Area of circle (r=2): 12.57</span></span>
<span class="line"><span>Square of 5: 25</span></span></code></pre></div><h4 id="步骤-2-扩展宏" tabindex="-1">步骤 2. 扩展宏 <a class="header-anchor" href="#步骤-2-扩展宏" aria-label="Permalink to &quot;步骤 2. 扩展宏&quot;">​</a></h4><p>您可以在编译前检查预处理器输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -E macro.c -o macro.i</span></span></code></pre></div><p>打开<code>macro.i</code>，你会看到全部<code>#include</code>文件被扩展，宏被替换为它们的值。</p><p>这是调试宏行为或检查标准标头扩展大小的好方法。</p><h4 id="步骤-3-类似函数的宏" tabindex="-1">步骤 3. 类似函数的宏 <a class="header-anchor" href="#步骤-3-类似函数的宏" aria-label="Permalink to &quot;步骤 3. 类似函数的宏&quot;">​</a></h4><p>宏看起来像函数，但它们是内联扩展的，这意味着没有调用开销，但也没有类型安全。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define ADD(a, b) ((a) + (b))</span></span></code></pre></div><p>用法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;%d\\n&quot;, ADD(2, 3));  // becomes ((2) + (3))</span></span></code></pre></div><p>小心缺少括号：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define BAD_ADD(a, b) a + b</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, 2 * BAD_ADD(3, 4)); // expands to 2 * 3 + 4 → 10, not 14</span></span></code></pre></div><p>始终将参数和整个表达式括在括号中。</p><h4 id="步骤-4-字符串化和标记粘贴" tabindex="-1">步骤 4. 字符串化和标记粘贴 <a class="header-anchor" href="#步骤-4-字符串化和标记粘贴" aria-label="Permalink to &quot;步骤 4. 字符串化和标记粘贴&quot;">​</a></h4><p>宏可以使用特殊运算符来操作文本。</p><p>字符串化 (<code>#</code>) 将参数转换为字符串文字：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define PRINT_EXPR(expr) printf(#expr &quot; = %d\\n&quot;, expr)</span></span></code></pre></div><p>用法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x = 5, y = 10;</span></span>
<span class="line"><span>PRINT_EXPR(x + y);  // prints: x + y = 15</span></span></code></pre></div><p>标记粘贴 (<code>##</code>) 连接标记：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define MAKE_VAR(name, num) name##num</span></span>
<span class="line"><span>int MAKE_VAR(counter, 1) = 42;  // becomes int counter1 = 42;</span></span></code></pre></div><h4 id="步骤-5-条件编译" tabindex="-1">步骤 5. 条件编译 <a class="header-anchor" href="#步骤-5-条件编译" aria-label="Permalink to &quot;步骤 5. 条件编译&quot;">​</a></h4><p>您可以根据条件包含或排除代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define DEBUG 1</span></span>
<span class="line"><span>#if DEBUG</span></span>
<span class="line"><span>    #define LOG(msg) printf(&quot;DEBUG: %s\\n&quot;, msg)</span></span>
<span class="line"><span>#else</span></span>
<span class="line"><span>    #define LOG(msg)</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>用法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    LOG(&quot;Starting program&quot;);</span></span>
<span class="line"><span>    printf(&quot;Running main logic\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译有或没有<code>-DDEBUG=1</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -DDEBUG=1 log.c -o log</span></span></code></pre></div><p>您还可以使用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifdef DEBUG</span></span>
<span class="line"><span>#ifndef RELEASE</span></span></code></pre></div><h4 id="步骤-6-接头护罩" tabindex="-1">步骤 6. 接头护罩 <a class="header-anchor" href="#步骤-6-接头护罩" aria-label="Permalink to &quot;步骤 6. 接头护罩&quot;">​</a></h4><p>通过使用预处理器防护来防止多次包含同一头文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef MY_HEADER_H</span></span>
<span class="line"><span>#define MY_HEADER_H</span></span>
<span class="line"><span>void greet(void);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>如果<code>MY_HEADER_H</code>已经定义，内容被跳过。这可以防止跨多个包含的重复定义。</p><h4 id="步骤-7-内置宏" tabindex="-1">步骤 7. 内置宏 <a class="header-anchor" href="#步骤-7-内置宏" aria-label="Permalink to &quot;步骤 7. 内置宏&quot;">​</a></h4><p>编译器自动定义了一些方便的宏：</p><table tabindex="0"><thead><tr><th>宏</th><th>扩展到</th></tr></thead><tbody><tr><td><code>__FILE__</code></td><td>当前文件名</td></tr><tr><td><code>__LINE__</code></td><td>当前行号</td></tr><tr><td><code>__DATE__</code></td><td>编译日期</td></tr><tr><td><code>__TIME__</code></td><td>编译时间</td></tr><tr><td><code>__func__</code></td><td>当前函数名称 (C99+)</td></tr></tbody></table><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;Error at %s:%d in %s()\\n&quot;, __FILE__, __LINE__, __func__);</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error at macro.c:10 in main()</span></span></code></pre></div><h4 id="小代码-调试宏" tabindex="-1">小代码：调试宏 <a class="header-anchor" href="#小代码-调试宏" aria-label="Permalink to &quot;小代码：调试宏&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define DEBUG_PRINT(fmt, ...) \\</span></span>
<span class="line"><span>    fprintf(stderr, &quot;[%s:%d] &quot; fmt &quot;\\n&quot;, __FILE__, __LINE__, __VA_ARGS__)</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int x = 10;</span></span>
<span class="line"><span>    DEBUG_PRINT(&quot;x = %d&quot;, x);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[macro.c:5] x = 10</span></span></code></pre></div><p>这就是使用宏在 C 中实现日志记录框架的方式。</p><h4 id="步骤-8-取消定义和重新定义" tabindex="-1">步骤 8. 取消定义和重新定义 <a class="header-anchor" href="#步骤-8-取消定义和重新定义" aria-label="Permalink to &quot;步骤 8. 取消定义和重新定义&quot;">​</a></h4><p>您可以使用以下命令删除宏<code>#undef</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#undef PI</span></span>
<span class="line"><span>#define PI 3.14</span></span></code></pre></div><p>这通常在大型项目中使用，以避免库之间的宏名称冲突。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>预处理器在编译时赋予 C 灵活性和强大功能，从而能够：</p><ul><li>跨平台构建（条件编译）</li><li>调试日志系统</li><li>内联性能优化</li><li>简化的配置管理</li></ul><p>它也是一把双刃剑，过度使用宏会使代码难以调试和维护。现代 C 在大多数用例中都支持内联函数（参见第 54 节），但宏对于低级系统工作仍然是不可或缺的。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>编写一个宏，在没有临时变量的情况下交换两个变量。</li><li>实施<code>LOG(level, msg)</code>仅当以下情况时才打印消息的宏<code>level &gt;= MIN_LOG_LEVEL</code>.</li><li>使用<code>__DATE__</code>和<code>__TIME__</code>打印构建信息。</li><li>为您的所有内容添加标头防护<code>.h</code>文件并测试多个包含项。</li><li>尝试<code>gcc -E</code>在不同的程序上了解预处理如何改变源。</li></ol><p>在下一节中，您将深入了解条件编译，根据平台、功能或调试需求控制程序的哪些部分是构建的。</p>`,70)])])}const g=s(p,[["render",i]]);export{u as __pageData,g as default};
